{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C56"],
      "claim": "Posaconazole delayed-release tablet has an absolute oral bioavailability of about 50% in healthy volunteers, supporting F >= 20%."
    },
    {
      "card_ids": ["C43"],
      "claim": "Cilomilast oral solution has a mean absolute bioavailability of 96% in healthy volunteers, well above the 20% threshold."
    },
    {
      "card_ids": ["C23"],
      "claim": "Pentazocine tablets have a mean absolute bioavailability of 18% in healthy subjects, below the 20% threshold."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C23"],
  "decision_summary": "Most high-transfer evidence molecules show absolute oral bioavailability of 50% or higher in healthy adults, clearly above the 20% threshold; one direct negative value (pentazocine 18%) is outweighed by the positive majority.",
  "evidence_gaps": [
    "Pediatric and special-population records for posaconazole and KNI-272 report low F values (16-16.5% and 12%), creating population-dependent uncertainty.",
    "One record measures a metabolite (S-9780/perindoprilat) rather than parent bioavailability, limiting its directness."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C56", "C43"],
  "revision_action": "initial",
  "supportive_card_ids": ["C56", "C43"]
}

